ruleToc.chapterList:
@js:
let textList = java.getStringList('@css:.sso_a li@text')
let url = java.getString('@@.sso_a@li.0@a@href')
let id = url.match(/id=(\d+)/)[1]
let mulu = []
for(let i=0;i<textList.length;i++,id++){
	mulu.push({
		text:textList[i],
		href:'http://m.uwuxs.com/uwuxs.asp?id='+id
		})
}
mulu

